// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz the sender, a single recipient, and the value
    function testFuzz_property(address from, address to, uint256 v) public {
        // keep addresses non-zero to be sensible
        vm.assume(from != address(0));
        vm.assume(to != address(0));

        // deploy a recorder that exposes a function matching transferFrom(address,address,uint256)
        Recorder r = new Recorder();

        // build single-element array for _tos so we can reason about exactly one call
        address[] memory tos = new address[](1);
        tos[0] = to;

        // call transfer on c with the recorder as the callee address
        bool ok;
        try c.transfer(from, address(r), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract always encodes the selector for transferFrom(address,address,uint256)
        // and invokes the callee with (from, to, v). Our Recorder exposes that exact function and records
        // the selector and decoded args. We assert that the call succeeded (ok == true) AND the recorder
        // observed the selector for transferFrom and observed the same (from,to,v) that we passed.
        // This is a universal property of the reference; the mutant using a different selector can
        // dispatch to a different function or fallback and so will fail to record the expected selector/args
        // for some inputs.

        bytes4 expectedSelector = bytes4(keccak256("transferFrom(address,address,uint256)"));

        // single assertion reading c's observable behavior via the recorder's public getters
        // assert that call succeeded and recorder saw expected selector and args
        assertTrue(
            ok && r.callCount() == 1 && r.lastSelector() == expectedSelector && r.lastFrom() == from && r.lastTo() == to && r.lastValue() == v
        );
    }
}

// Recorder that defines transferFrom with the exact ABI the reference encodes and records the call
contract Recorder {
    uint256 public calls;
    bytes4 public lastSel;
    address public last_from;
    address public last_to;
    uint256 public last_value;

    // function matching the ABI the reference uses
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        lastSel = msg.sig;
        last_from = from;
        last_to = to;
        last_value = v;
        return true;
    }

    // expose getters with the exact names used in the test
    function callCount() external view returns (uint256) { return calls; }
    function lastSelector() external view returns (bytes4) { return lastSel; }
    function lastFrom() external view returns (address) { return last_from; }
    function lastTo() external view returns (address) { return last_to; }
    function lastValue() external view returns (uint256) { return last_value; }
}
